import re


class KeyHintDict(dict):
    """
    Print all available dict keys, while raising KeyError
    """

    def __getitem__(self, item):
        try:
            item = super(KeyHintDict, self).__getitem__(item)
        except KeyError:
            raise KeyError("Key '{}' not found in dict. Available keys: {}".format(item, list(self.keys())))
        else:
            return item


def create_dict(list_of_output_parsed_lines):
    """
    Example list_of_output_parsed_lines:
    [
    ...  ['field1', 'field2'],
    ...  ['value11', 'value12'],
    ...  ['value21', 'value22']
    ]

    Example output dict:
    {
    ...  'field1': ['value11', 'value21'],
    ...  'field2': ['value12', 'value22']
    }

    :param list_of_output_parsed_lines: list of equal sized lists
    :return:
    """
    d = KeyHintDict()
    field_list = []
    for index, line in enumerate(list_of_output_parsed_lines):
        if index == 0:
            field_list = list(line)
        else:
            for value_index, value in enumerate(line):
                d.setdefault(field_list[value_index], []).append(value)
    return d


def create_dict_with_key(key, list_of_output_parsed_lines, list_of_regexp_submissions=None):
    """
    Example list_of_output_parsed_lines:
    [
    ...  ['field1', 'field2'],
    ...  ['value11', 'value12'],
    ...  ['value21', 'value22']
    ]

    Example output dict with key:
    {
    ... 'value11':
    ...     {
    ...         'field1': 'value11',
    ...         'field2': 'value12'
    ...     },
    ... 'value21':
    ...     {
    ...         'field1': 'value21',
    ...         'field2': 'value22'
    ...     }
    }

    :param key: main dict key
    :param list_of_output_parsed_lines: list of equal sized lists
    :param list_of_regexp_submissions: list of submissions for both key and value
    :return:
    """
    d = KeyHintDict()
    field_list = []
    key_index = None
    for index, line in enumerate(list_of_output_parsed_lines):
        if index == 0:
            field_list = list(line)
            key_index = field_list.index(key)
        else:
            for value_index, value in enumerate(line):
                key = line[key_index]
                field = field_list[value_index]
                if list_of_regexp_submissions is not None:
                    for (old, new) in list_of_regexp_submissions:
                        value = re.sub(old, new, value)
                        key = re.sub(old, new, key)
                        field = re.sub(old, new, field)
                d.setdefault(key, KeyHintDict())[field] = value
    return d


def create_dict_with_key_in_dict(key, subkey, list_of_output_parsed_lines):
    """
    Example list_of_output_parsed_lines:
    [
    ...  ['field1', 'field2'],
    ...  [
    ...      {'subkey1': 'value11',
    ...       'subkey2': 'value111'},
    ...      'value12'],
    ...  [
    ...      {'subkey1': 'value21',
    ...       'subkey2': 'value211'},
    ...      'value22']
    ]

    Example output dict:
    {
    ... 'value111':
    ...     {
    ...         'field1': {
    ...             'subkey1': 'value11',
    ...             'subkey2': 'value111'
    ...         },
    ...         'field2': 'value12'
    ...     },
    ... 'value211':
    ...     {
    ...         'field1': {
    ...             'subkey1': 'value21',
    ...             'subkey2': 'value211'
    ...         },
    ...         'field2': 'value22'
    ...     }
    ...
    }

    :param key: some field which return dict
    :param subkey: some subkey that exists dict under key
    :param list_of_output_parsed_lines:
    :return:
    """
    d = KeyHintDict()
    field_list = []
    key_index = None
    for index, line in enumerate(list_of_output_parsed_lines):
        if index == 0:
            field_list = list(line)
            key_index = field_list.index(key)
        else:
            for value_index, value in enumerate(line):
                d.setdefault(line[key_index][subkey], KeyHintDict())[field_list[value_index]] = value
    return d
